    let pragma = 'React.createElement';
    let frag = null;
    const m = /@jsx\s+([A-Za-z_$][\w$.]*)/.exec(source);
    if (m) pragma = m[1];
    const fm = /@jsxFrag\s+([A-Za-z_$][\w$.]*)/.exec(source);
