    const len = source.length;
    if (ch === '/' && next === '/') {
      const e = source.indexOf('\n', i);
      return e === -1 ? len : e;
    }
    if (ch === '/' && next === '*') {
      const e = source.indexOf('*/', i + 2);
      return e === -1 ? len : e + 2;
    }
    if (ch === '"' || ch === "'") {
      let j = i + 1;
      while (j < len) {
        const c = source[j];
        if (c === '\\') { j += 2; continue; }
        if (c === ch) { j++; break; }
        if (c === '\n') break;
        j++;
      }
      return j;
    }
    if (ch === '`') {
      let j = i + 1;
      let depth = 0;
      while (j < len) {
        const c = source[j];
        if (c === '\\') { j += 2; continue; }
        if (c === '$' && source[j + 1] === '{') { depth++; j += 2; continue; }
        if (c === '}' && depth > 0) { depth--; j++; continue; }
        if (c === '`' && depth === 0) { j++; break; }
        j++;
      }
      return j;
    }
    return -1;
