        const existing = portTable.getChaosRule(toPort) || { partitionFromPorts: [] };
        const list = Array.from(new Set([...(existing.partitionFromPorts || []), fromPort]));
        portTable.setChaosRule(toPort, { partitionFromPorts: list });
